pub fn decode_parse_result(buf []u8) ParseAstResult {
	mut version := 0
	mut stmts := []AstRawStmt{}
	mut off := 0
	for off < buf.len {
		field_num, wire_type, c := read_tag(buf, off)
		off += c
		match field_num {
			1 {
				v, c2 := read_varint_i64(buf, off)
				version = int(v)
				off += c2
			}
			2 {
				data, c2 := read_submessage(buf, off)
				rs, _ := decode_raw_stmt(data, max_decode_depth)
				stmts << AstRawStmt{
					stmt_location: rs.stmt_location
					stmt_len: rs.stmt_len
					stmt: rs.stmt
				}
				off += c2
			}
			else {
				off = skip_field(buf, off, wire_type)
			}
		}
	}
	return ParseAstResult{
		version: version
		stmts: stmts
	}
}

